def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_last, opp_last = history[-1]
    if n == 99:
        return 'D'
    opp_def = 0
    my_def = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_def += 1
        if history[i][0] == 'D':
            my_def += 1
    if n < 4:
        return 'C'
    last3 = history[-3:]
    opp_d3 = 0
    for i in range(3):
        if last3[i][1] == 'D':
            opp_d3 += 1
    if opp_d3 == 3:
        return 'D' if rng.random() < 0.9 else 'C'
    if opp_last == 'D':
        if my_last == 'C':
            return 'D' if rng.random() < 0.85 else 'C'
        if opp_def > my_def:
            return 'D' if rng.random() < 0.6 else 'C'
        return 'C'
    if n >= 90:
        if opp_def * 4 < n:
            return 'C'
        if opp_def * 2 > n:
            return 'D'
    recent = history[-8:]
    rd = 0
    for i in range(len(recent)):
        if recent[i][1] == 'D':
            rd += 1
    if rd == 0:
        return 'C'
    if rd >= 4:
        return 'D'
    if opp_def * 5 < n and n > 20:
        if rd == 1 and rng.random() < 0.2:
            return 'D'
        return 'C'
    if my_last == 'D' and opp_last == 'C':
        return 'C'
    return 'C'
